begin;
with j as (select * from jsonb_to_recordset($law7d0059$[{"code_id":"NK_RF","article_number":"32","version_date":"2000-07-31","article_text":"1. Налоговые органы обязаны:\n\n1) соблюдать законодательство о налогах и сборах;\n\n2) осуществлять контроль за соблюдением законодательства о налогах и сборах, а также принятых в соответствии с ним нормативных правовых актов;\n\n3) вести в установленном порядке учет организаций и физических лиц;\n\n4) бесплатно информировать (в том числе в письменной форме) налогоплательщиков, плательщиков сборов и налоговых агентов о действующих налогах и сборах, законодательстве о налогах и сборах и о принятых в соответствии с ним нормативных правовых актах, порядке исчисления и уплаты налогов и сборов, правах и обязанностях налогоплательщиков, плательщиков сборов и налоговых агентов, полномочиях налоговых органов и их должностных лиц, а также представлять формы налоговых деклараций (расчетов) и разъяснять порядок их заполнения;\n\n41) передавать налогоплательщикам, указанным в пунктах 2 и 3 статьи 112 настоящего Кодекса, в электронной форме квитанцию о приеме при получении документов, переданных в налоговый орган через личный кабинет налогоплательщика; (Дополнение подпунктом - Федеральный закон от 04.11.2014 № 347-ФЗ) (В редакции Федерального закона от 03.07.2016 № 244-ФЗ)\n\n5) руководствоваться письменными разъяснениями Министерства финансов Российской Федерации по вопросам применения законодательства Российской Федерации о налогах и сборах;\n\n6) доводить до сведения налогоплательщиков, плательщиков сборов и налоговых агентов информацию о реквизитах счета Федерального казначейства, об их изменении и иную информацию, необходимую для заполнения поручений на перечисление налогов, сборов, уплачиваемых не в качестве единого налогового платежа; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n7) осуществлять возврат лицу - налогоплательщику, плательщику сбора или налоговому агенту денежных средств в размере, не превышающем положительное сальдо единого налогового счета такого лица, или осуществлять зачет указанных денежных средств в счет исполнения обязанности другого лица по уплате налогов, сборов, страховых взносов, пеней, штрафов и (или) процентов, в счет исполнения предстоящей обязанности по уплате конкретного налога (сбора, страхового взноса) либо в счет исполнения решений налоговых органов, указанных в подпунктах 10 и 11 пункта 5 и подпункте 3 пункта 7 статьи 113 настоящего Кодекса, в порядке, предусмотренном настоящим Кодексом; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n8) соблюдать налоговую тайну и обеспечивать ее сохранение;\n\n9) направлять налогоплательщику, плательщику сбора или налоговому агенту копии акта налоговой проверки и решения налогового органа, а также в случаях, предусмотренных настоящим Кодексом, налоговое уведомление и (или) требование об уплате задолженности; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n10) представлять налогоплательщику, плательщику сбора или налоговому агенту по его запросу, переданному в налоговый орган в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика либо на бумажном носителе, справку о наличии по состоянию на дату формирования справки положительного, отрицательного или нулевого сальдо единого налогового счета такого налогоплательщика, плательщика сбора или налогового агента, справку о принадлежности сумм денежных средств, перечисленных в качестве единого налогового платежа, и справку об исполнении обязанности по уплате налогов, сборов, пеней, штрафов, процентов по состоянию на дату формирования справки на основании данных налогового органа в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика либо на бумажном носителе в порядке, установленном федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nСправка о наличии положительного, отрицательного или нулевого сальдо единого налогового счета и справка о принадлежности сумм денежных средств, перечисленных в качестве единого налогового платежа, представляются лицу, указанному в пункте 4 статьи 113 настоящего Кодекса (его представителю), в течение пяти дней со дня поступления в налоговый орган соответствующих запросов, справка об исполнении обязанности по уплате налогов, сборов, пеней, штрафов, процентов - в течение десяти дней со дня поступления в налоговый орган соответствующего запроса.\n\nПри этом справка о наличии отрицательного сальдо должна содержать имеющиеся в налоговом органе детализированные сведения об обязанности лица, указанного в пункте 4 статьи 113 настоящего Кодекса, по уплате налогов (авансовых платежей по налогам, сборов, страховых взносов, пеней, штрафов, процентов).\n\nСправка о принадлежности сумм денежных средств, перечисленных в качестве единого налогового платежа, формируется за период, не превышающий трех лет, предшествующих дню поступления в налоговый орган соответствующего запроса, и должна содержать сведения о всех денежных средствах, поступивших и признаваемых в качестве единого налогового платежа, и иных суммах, признаваемых в качестве единого налогового платежа, с указанием их принадлежности, определенной на дату формирования справки;\n\n(Подпункт в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n101) (Дополнение подпунктом - Федеральный закон от 16.11.2011 № 321-ФЗ) (Утратил силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n11) (Подпункт утратил силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n12) по заявлению налогоплательщика, плательщика сбора или налогового агента выдавать копии решений, принятых налоговым органом в отношении этого налогоплательщика, плательщика сбора или налогового агента;\n\n13) по заявлению ответственного участника консолидированной группы налогоплательщиков выдавать копии решений, принятых налоговым органом в отношении консолидированной группы налогоплательщиков; (Дополнение подпунктом - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n14) представлять пользователям выписки из Единого государственного реестра налогоплательщиков; (Дополнение подпунктом - Федеральный закон от 23.07.2013 № 248-ФЗ)\n\n15) представлять в электронной форме в порядке, определяемом соглашением взаимодействующих сторон, в территориальные органы Фонда пенсионного и социального страхования Российской Федерации, Федерального фонда обязательного медицинского страхования сведения о наделении обособленных подразделений (включая филиалы, представительства) российских организаций, созданных на территории Российской Федерации, полномочиями (о лишении полномочий) по начислению выплат и иных вознаграждений в пользу физических лиц, об изменении места нахождения обособленных подразделений (за исключением филиалов, представительств), о прекращении деятельности указанных организаций через такие обособленные подразделения (о закрытии таких обособленных подразделений), о постановке на учет (снятии с учета) в налоговых органах иностранных организаций, осуществляющих деятельность на территории Российской Федерации, международных организаций в качестве плательщиков страховых взносов, физических лиц в качестве адвокатов, нотариусов, занимающихся частной практикой, арбитражных управляющих, занимающихся частной практикой оценщиков, патентных поверенных, медиаторов и иных физических лиц - плательщиков страховых взносов не позднее трех дней, следующих за днем внесения в Единый государственный реестр налогоплательщиков указанных сведений; (Дополнение подпунктом - Федеральный закон от 03.07.2016 № 243-ФЗ) (В редакции  федеральных законов от 30.11.2016 № 401-ФЗ, от 14.07.2022 № 239-ФЗ)\n\n16) по заявлению налогоплательщика представлять налогоплательщику (его представителю) документ в электронной форме или на бумажном носителе, подтверждающий статус налогового резидента Российской Федерации, в порядке, по форме и формату, которые утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов; (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n17) представлять в электронной форме в порядке, определяемом соглашением взаимодействующих сторон, в территориальные органы Фонда пенсионного и социального страхования Российской Федерации сведения о постановке на учет (снятии с учета) в налоговых органах физических лиц, в том числе индивидуальных предпринимателей, в качестве налогоплательщиков налога на профессиональный доход, признаваемых таковыми в соответствии с Федеральным законом от 27 ноября 2018 года № 422-ФЗ \"О проведении эксперимента по установлению специального налогового режима \"Налог на профессиональный доход\", не позднее трех дней, следующих за днем внесения в Единый государственный реестр налогоплательщиков указанных сведений. (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции  федеральных законов от 28.01.2020 № 5-ФЗ, от 14.07.2022 № 239-ФЗ)\n\n2. Налоговые органы несут также другие обязанности, предусмотренные настоящим Кодексом и иными федеральными законами.\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 32. Обязанности налоговых органов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f951ab496a45a5937d0917aadc6c861f38afd8348c877809a1138b338d013b8"},{"code_id":"NK_RF","article_number":"33","version_date":"2000-07-31","article_text":"Должностные лица налоговых органов обязаны:\n\n1) действовать в строгом соответствии с настоящим Кодексом и иными федеральными законами;\n\n2) реализовывать в пределах своей компетенции права и обязанности налоговых органов;\n\n3) корректно и внимательно относиться к налогоплательщикам, их представителям и иным участникам отношений, регулируемых законодательством о налогах и сборах, не унижать их честь и достоинство. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 33. Обязанности должностных лиц налоговых органов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c101bce3215b56566e674b0e7d3232c668883df903b9af6bd2b55d70eb987311"},{"code_id":"NK_RF","article_number":"34.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратила силу - Федеральный закон от 29.06.2004 № 58-ФЗ)","article_title":"Статья 34.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f034394fc39cf58740a722f96dd42f7ef1b6f2ccc1e9d3a810c3e95927b8e3a"},{"code_id":"NK_RF","article_number":"34.2","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nн от 27.07.2006 № 137-ФЗ) (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 29.06.2004 № 58-ФЗ)","article_title":"Статья 34.2. Полномочия финансовых органов в области налогов, сборов, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"242ae03ab281e5f15f9fb77ea16cad754e2b1a04fd6219eb8b8bcfe50c3663e8"},{"code_id":"NK_RF","article_number":"35","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 29.06.2004 № 58-ФЗ)\n\nПричиненные налогоплательщикам, плательщикам сборов, плательщикам страховых взносов и налоговым агентам убытки возмещаются за счет федерального бюджета в порядке, предусмотренном настоящим Кодексом и иными федеральными законами. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n(Наименование в редакции федеральных законов от 30.06.2003 № 86-ФЗ; от 28.12.2010 № 404-ФЗ)","article_title":"Статья 35. Ответственность налоговых органов, таможенных органов, а также их должностных лиц","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86ca237da13167275c3c54ce491291955ecf07553a30a76cf76356e997e97b8f"},{"code_id":"NK_RF","article_number":"36","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 28.12.2010 № 404-ФЗ)\n\n1. По запросу налоговых органов органы внутренних дел участвуют вместе с налоговыми органами в проводимых налоговыми органами выездных налоговых проверках.\n\n(Статья в редакции Федерального закона от 30.06.2003 № 86-ФЗ)","article_title":"Статья 36. Полномочия органов внутренних дел, следственных органов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"287972ab5b8f4163fd92b750d768609dbdaf0078b493cad4e1215dd9c1c5b53a"},{"code_id":"NK_RF","article_number":"37","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 30.06.2003 № 86-ФЗ; от 28.12.2010 № 404-ФЗ)\n\nПричиненные налогоплательщикам, плательщикам сборов, плательщикам страховых взносов и налоговым агентам при проведении мероприятий, предусмотренных пунктом 1 статьи 36 настоящего Кодекса, убытки возмещаются за счет федерального бюджета в порядке, предусмотренном настоящим Кодексом и иными федеральными законами. (В редакции федеральных законов от 30.06.2003 № 86-ФЗ; от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)","article_title":"Статья 37. Ответственность органов внутренних дел, следственных органов и их должностных лиц","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b8da6ca3ba9ef54332720ca42591a617847d8fb1d7348371165201ef84bcd6b3"},{"code_id":"NK_RF","article_number":"38","version_date":"2000-07-31","article_text":"Каждый налог имеет самостоятельный объект налогообложения, определяемый в соответствии с частью второй настоящего Кодекса и с учетом положений настоящей статьи.\n\nДля целей настоящего Кодекса не признаются имуществом имущественные права, за исключением безналичных денежных средств и бездокументарных ценных бумаг.\n\nДля целей настоящего Кодекса цифровая валюта (в том числе цифровая валюта, используемая в качестве средства платежа по внешнеторговым договорам (контрактам) в рамках экспериментального правового режима в сфере цифровых инноваций, установленного в соответствии со статьей 11 Федерального закона от 31 июля 2020 года № 259-ФЗ \"О цифровых финансовых активах, цифровой валюте и о внесении изменений в отдельные законодательные акты Российской Федерации\") признается имуществом. (Дополнение абзацем - Федеральный закон от 29.11.2024 № 418-ФЗ)\n\n(Пункт в редакции Федерального закона от 20.07.2020 № 219-ФЗ)\n\nПри определении идентичности товаров учитываются их физические характеристики, качество, функциональное назначение, страна происхождения и производитель, его деловая репутация на рынке и используемый товарный знак.\n\nПри определении идентичности работ (услуг) учитываются характеристики подрядчика (исполнителя), его деловая репутация на рынке и используемый товарный знак.\n\n(Дополнение пунктом - Федеральный закон от 18.07.2011 № 227-ФЗ)\n\nОднородными работами (услугами) признаются работы (услуги), которые, не являясь идентичными, имеют сходные характеристики, что позволяет им быть коммерчески и (или) функционально взаимозаменяемыми. При определении однородности работ (услуг) учитываются их качество, товарный знак, репутация на рынке, а также вид работ (услуг), их объем, уникальность и коммерческая взаимозаменяемость.\n\n(Дополнение пунктом - Федеральный закон от 18.07.2011 № 227-ФЗ)","article_title":"Статья 38. Объект налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d6874f9078939ecc6900a2d0443381b14804c4220b5bcf9c3ad5a91d5a77402d"},{"code_id":"NK_RF","article_number":"39","version_date":"2000-07-31","article_text":"1) осуществление операций, связанных с обращением российской или иностранной валюты (за исключением целей нумизматики);\n\n2) передача основных средств, нематериальных активов и (или) иного имущества организации ее правопреемнику (правопреемникам) при реорганизации этой организации;\n\n3) передача основных средств, нематериальных активов и (или) иного имущества некоммерческим организациям на осуществление основной уставной деятельности, не связанной с предпринимательской деятельностью; (Дополнение подпунктом - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\n4) передача имущества, если такая передача носит инвестиционный характер (в частности, вклады в уставный (складочный) капитал хозяйственных обществ и товариществ, вклады по договору простого товарищества (договору о совместной деятельности), договору инвестиционного товарищества, паевые взносы в паевые фонды кооперативов); (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 28.11.2011 № 336-ФЗ)\n\n41) передача имущества и (или) имущественных прав по концессионному соглашению, соглашению о государственно-частном партнерстве, соглашению о муниципально-частном партнерстве в соответствии с законодательством Российской Федерации; (Дополнение подпунктом - Федеральный закон от 30.06.2008 № 108-ФЗ) (В редакции Федерального закона от 25.12.2018 № 493-ФЗ)\n\n5) передача имущества в пределах первоначального взноса участнику хозяйственного общества или товарищества (его правопреемнику или наследнику) при выходе (выбытии) из хозяйственного общества или товарищества, а также при распределении имущества ликвидируемого хозяйственного общества или товарищества между его участниками; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n6) передача имущества в пределах первоначального взноса участнику договора простого товарищества (договора о совместной деятельности), договора инвестиционного товарищества или его правопреемнику в случае выдела его доли из имущества, находящегося в общей собственности участников договора, или раздела такого имущества; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 28.11.2011 № 336-ФЗ)\n\n7) передача жилых помещений физическим лицам в домах государственного или муниципального жилищного фонда при проведении приватизации; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n8) изъятие имущества путем конфискации, наследование имущества, а также обращение в собственность иных лиц бесхозяйных и брошенных вещей, бесхозяйных животных, находки, клада в соответствии с нормами Гражданского кодекса Российской Федерации; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n81) передача имущества участникам хозяйственного общества или товарищества при распределении имущества и имущественных прав ликвидируемой организации, являющейся иностранным организатором XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи или маркетинговым партнером Международного олимпийского комитета в соответствии со статьей 31 Федерального закона от 1 декабря 2007 года № 310-ФЗ \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\". Настоящее положение применяется в случае, если создание и ликвидация организации, являющейся иностранным организатором XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи или маркетинговым партнером Международного олимпийского комитета в соответствии со статьей 31 указанного Федерального закона, осуществляются в период организации XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, установленный частью 1 статьи 2 указанного Федерального закона; (Дополнение подпунктом - Федеральный закон от 30.07.2010 № 242-ФЗ)\n\n82) передача имущества номинальным владельцем его фактическому владельцу, если такое имущество и его номинальный владелец указаны в специальной декларации, представленной в соответствии с Федеральным законом \"О добровольном декларировании физическими лицами активов и счетов (вкладов) в банках и о внесении изменений в отдельные законодательные акты Российской Федерации\"; (Дополнение подпунктом - Федеральный закон от 08.06.2015 № 150-ФЗ)\n\n9) иные операции в случаях, предусмотренных настоящим Кодексом. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)","article_title":"Статья 39. Реализация товаров, работ или услуг","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"30d5ed64435b7b969061e056e595d06f1ed78a69d3cca12342fe4856f91454f2"},{"code_id":"NK_RF","article_number":"4","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 27.07.2006 № 137-ФЗ, от 03.07.2016 № 243-ФЗ, от 11.06.2021 № 199-ФЗ)\n\n1) приостановление, отмену или перенос на более поздний срок мероприятий налогового контроля, в том числе проверок полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами, а также приостановление течения сроков, предусмотренных настоящим Кодексом, в том числе сроков назначения (проведения) проверок, на период приостановления или переноса указанных мероприятий налогового контроля;\n\n2) продление установленных законодательством Российской Федерации о налогах и сборах сроков уплаты налогов (авансовых платежей по налогам), в том числе предусмотренных специальными налоговыми режимами, сборов, страховых взносов; (В редакции Федерального закона от 26.03.2022 № 67-ФЗ)\n\n3) продление установленных законодательством субъектов Российской Федерации о налогах и сборах и нормативными правовыми актами муниципальных образований о местных налогах и сборах сроков уплаты авансовых платежей по транспортному налогу, налогу на имущество организаций и земельному налогу;\n\n4) продление сроков представления в налоговые органы налоговых деклараций (расчетов), бухгалтерской (финансовой) отчетности и (или) иных документов (сведений);\n\n5) продление сроков направления и исполнения требований об уплате налогов, сборов, страховых взносов, пеней, штрафов, процентов, а также сроков принятия решений о взыскании налогов, сборов, страховых взносов, пеней, штрафов, процентов;\n\n6) дополнительные основания предоставления в 2020, 2022 - 2028 годах отсрочки (рассрочки) по уплате налогов, страховых взносов, пеней, штрафов, процентов, изменение порядка и условий ее предоставления; (В редакции  федеральных законов от 09.03.2022 № 52-ФЗ, от 21.11.2022 № 443-ФЗ, от 19.12.2023 № 611-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n7) основания и условия неприменения или особенности применения способов обеспечения исполнения обязанности по уплате налогов, сборов, страховых взносов;\n\n8) основания и условия неприменения ответственности за непредставление (несвоевременное представление) в налоговые органы налоговых деклараций (расчетов), бухгалтерской (финансовой) отчетности и (или) иных документов (сведений);\n\n9) особенности взыскания задолженности за счет денежных средств на счетах налогоплательщика (плательщика сбора, плательщика страховых взносов) - организации, индивидуального предпринимателя или налогового агента - организации, индивидуального предпринимателя. (Дополнение подпунктом - Федеральный закон от 19.12.2023 № 611-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 01.04.2020 № 102-ФЗ)\n\nабря 2024 года (включительно) издавать нормативные правовые акты, предусматривающие особенности неприменения ответственности в 2024 году к лицам, состоящим на учете в налоговых органах по месту нахождения (месту жительства) на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области. (Дополнение пунктом - Федеральный закон от 28.12.2022 № 564-ФЗ) (В редакции  Федерального закона от 19.12.2023 № 611-ФЗ)\n\nВ случае, если в соответствии с настоящим пунктом сроки уплаты налогов, предусмотренных специальными налоговыми режимами, региональных и местных налогов (авансовых платежей по налогам), торгового сбора продлеваются для отдельных категорий налогоплательщиков, при принятии указанных в настоящем пункте нормативных правовых актов и установлении критериев определения этих категорий налогоплательщиков учитываются следующие показатели: основные виды экономической деятельности, которые осуществляют налогоплательщики по состоянию на 1 марта 2020 года (в отношении указанных актов и критериев, принятых в 2020 году), на 1 марта 2022 года (в отношении указанных актов и критериев, принятых в 2022 году); данные, содержащиеся в реестрах, ведение которых осуществляет федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в налоговой или бухгалтерской (финансовой) отчетности. (В редакции Федерального закона от 09.03.2022 № 52-ФЗ)\n\nВ случае определения указанных категорий на основе иных критериев уполномоченный орган исполнительной власти субъекта Российской Федерации формирует соответствующий перечень налогоплательщиков с указанием их идентификационных номеров, который направляется в налоговый орган по субъекту Российской Федерации в электронной форме.\n\n(Дополнение пунктом - Федеральный закон от 01.04.2020 № 102-ФЗ)\n\n(Статья в редакции Федерального закона от 29.06.2004 № 58-ФЗ)","article_title":"Статья 4. Нормативные правовые акты Правительства Российской Федерации, федеральных органов исполнительной власти, органов исполнительной власти субъектов Российской Федерации, исполнительных органов местного самоуправления, исполнительно-распорядительного органа федеральной территории \"Сириус\"","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f787f2c3e22dfbaabf7fcbb95abf561d840a75911274017a03e9db048a6803a1"},{"code_id":"NK_RF","article_number":"40","version_date":"2000-07-31","article_text":"1. Если иное не предусмотрено настоящей статьей, для целей налогообложения принимается цена товаров, работ или услуг, указанная сторонами сделки. Пока не доказано обратное, предполагается, что эта цена соответствует уровню рыночных цен.\n\n1) между взаимозависимыми лицами;\n\n2) по товарообменным (бартерным) операциям;\n\n3) при совершении внешнеторговых сделок; (Дополнение подпунктом - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\n4) при отклонении более чем на 20 процентов в сторону повышения или в сторону понижения от уровня цен, применяемых налогоплательщиком по идентичным (однородным) товарам (работам, услугам) в пределах непродолжительного периода времени. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nРыночная цена определяется с учетом положений, предусмотренных пунктами 4 - 11 настоящей статьи. При этом учитываются обычные при заключении сделок между невзаимозависимыми лицами надбавки к цене или скидки. В частности, учитываются скидки, вызванные:\n\nсезонными и иными колебаниями потребительского спроса на товары (работы, услуги);\n\nпотерей товарами качества или иных потребительских свойств;\n\nистечением (приближением даты истечения) сроков годности или реализации товаров;\n\nмаркетинговой политикой, в том числе при продвижении на рынки новых товаров, не имеющих аналогов, а также при продвижении товаров (работ, услуг) на новые рынки;\n\nреализацией опытных моделей и образцов товаров в целях ознакомления с ними потребителей.\n\n(Пункт в редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nПри определении идентичности товаров учитываются, в частности, их физические характеристики, качество и репутация на рынке, страна происхождения и производитель. При определении идентичности товаров незначительные различия в их внешнем виде могут не учитываться. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nПри определении однородности товаров учитываются, в частности, их качество, наличие товарного знака, репутация на рынке, страна происхождения.\n\nАбзац. (Исключен - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\nПри этом условия сделок на рынке идентичных (а при их отсутствии - однородных) товаров, работ или услуг признаются сопоставимыми, если различие между такими условиями либо существенно не влияет на цену таких товаров, работ или услуг, либо может быть учтено с помощью поправок.\n\n(Пункт в редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n(Пункт 10 исключен  - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\n10. При отсутствии на соответствующем рынке товаров, работ или услуг сделок по идентичным (однородным) товарам, работам, услугам или из-за отсутствия предложения на этом рынке таких товаров, работ или услуг, а также при невозможности определения соответствующих цен ввиду отсутствия либо недоступности информационных источников для определения рыночной цены используется метод цены последующей реализации, при котором рыночная цена товаров, работ или услуг, реализуемых продавцом, определяется как разность цены, по которой такие товары, работы или услуги реализованы покупателем этих товаров, работ или услуг при последующей их реализации (перепродаже), и обычных в подобных случаях затрат, понесенных этим покупателем при перепродаже (без учета цены, по которой были приобретены указанным покупателем у продавца товары, работы или услуги) и продвижении на рынок приобретенных у покупателя товаров, работ или услуг, а также обычной для данной сферы деятельности прибыли покупателя.\n\nПри невозможности использования метода цены последующей реализации (в частности, при отсутствии информации о цене товаров, работ или услуг, в последующем реализованных покупателем) используется затратный метод, при котором рыночная цена товаров, работ или услуг, реализуемых продавцом, определяется как сумма произведенных затрат и обычной для данной сферы деятельности прибыли. При этом учитываются обычные в подобных случаях прямые и косвенные затраты на производство (приобретение) и (или) реализацию товаров, работ или услуг, обычные в подобных случаях затраты на транспортировку, хранение, страхование и иные подобные затраты.\n\n(Пункт в редакции Федерального закона от 09.07.1999 № 154-ФЗ)","article_title":"Статья 40. Принципы определения цены товаров, работ или услуг для целей налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1d54ce31514437f459378fa4c81cad2174d7aea45e24dd02ba4f75a4f409530"},{"code_id":"NK_RF","article_number":"43","version_date":"2000-07-31","article_text":"К дивидендам также относятся любые доходы, получаемые из источников за пределами Российской Федерации, относящиеся к дивидендам в соответствии с законодательствами иностранных государств. (Дополнение абзацем - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\n1) выплаты при ликвидации организации акционеру (участнику) этой организации в денежной или натуральной форме, не превышающие взноса этого акционера (участника) в уставный (складочный) капитал организации; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n2) выплаты акционерам (участникам) организации в виде передачи акций этой же организации в собственность;\n\n3) выплаты некоммерческой организации на осуществление ее основной уставной деятельности (не связанной с предпринимательской деятельностью), произведенные хозяйственными обществами, уставный капитал которых состоит полностью из вкладов этой некоммерческой организации. (Дополнение подпунктом - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\n(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)","article_title":"Статья 43. Дивиденды и проценты","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a688ae912cf8a3ec774abbd55a8ae731d6e1f7229b517f7be51cd0f376d08b0d"},{"code_id":"NK_RF","article_number":"44","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n1. Обязанность по уплате налога или сбора возникает, изменяется и прекращается при наличии оснований, установленных настоящим Кодексом или иным актом законодательства о налогах и сборах.\n\n2. Обязанность по уплате конкретного налога или сбора возлагается на налогоплательщика и плательщика сбора с момента возникновения установленных законодательством о налогах и сборах обстоятельств, предусматривающих уплату данного налога или сбора.\n\n3. Обязанность по уплате налога и (или) сбора прекращается:\n\n1) с уплатой налога и (или) сбора в случаях, предусмотренных настоящим Кодексом; (В редакции федеральных законов от 16.11.2011 № 321-ФЗ; от 30.11.2016 № 401-ФЗ)\n\n2) (Подпункт утратил силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n3) со смертью физического лица - налогоплательщика или с объявлением его умершим в порядке, установленном гражданским процессуальным законодательством Российской Федерации. Задолженность по налогам, указанным в пункте 3 статьи 14 и пунктах 1 и 2 статьи 15 настоящего Кодекса, умершего лица либо лица, объявленного умершим, погашается наследниками в пределах стоимости наследственного имущества в порядке, установленном гражданским законодательством Российской Федерации для оплаты наследниками долгов наследодателя; (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 27.11.2017 № 335-ФЗ)\n\n4) с ликвидацией организации-налогоплательщика - после проведения всех расчетов с бюджетной системой Российской Федерации в соответствии со статьей 49 настоящего Кодекса; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n5) с возникновением иных обстоятельств, с которыми законодательство о налогах и сборах связывает прекращение обязанности по уплате соответствующего налога или сбора. (Дополнение подпунктом - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 44. Возникновение, изменение и прекращение обязанности по уплате налога, сбора, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e49fcae06682b95a4e84d78b9995b49125a4a058e6ab9e16eef03a47b21eb8b"},{"code_id":"NK_RF","article_number":"45","version_date":"2000-07-31","article_text":"1. Налогоплательщик обязан самостоятельно исполнить обязанность по уплате налога посредством перечисления денежных средств в качестве единого налогового платежа, если иное не предусмотрено законодательством Российской Федерации о налогах и сборах.\n\nОбязанность по уплате налога должна быть исполнена в срок, установленный в соответствии с настоящим Кодексом. Налогоплательщик вправе перечислить денежные средства в счет исполнения обязанности по уплате налога до наступления установленного срока. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nПеречисление денежных средств в счет исполнения обязанности налогоплательщика по уплате налога может быть произведено иным лицом. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nИное лицо не вправе требовать возврата уплаченного за налогоплательщика единого налогового платежа и налога, уплаченного не в качестве единого налогового платежа. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n2. Если иное не предусмотрено пунктами 4 и 5 настоящей статьи, в случае неуплаты или неполной уплаты налога в установленный срок производится взыскание задолженности в порядке, предусмотренном настоящим Кодексом.\n\n3. Взыскание задолженности с организации или индивидуального предпринимателя производится в порядке, предусмотренном статьями 46 и 47 настоящего Кодекса. Взыскание налога с физического лица, не являющегося индивидуальным предпринимателем, производится в порядке, предусмотренном статьей 48 настоящего Кодекса. Взыскание задолженности в судебном порядке производится:\n\n1) в целях взыскания задолженности, возникшей по итогам проведенной налоговой проверки, числящейся более трех месяцев:\n\nза организациями, являющимися в соответствии с гражданским законодательством Российской Федерации зависимыми (дочерними) обществами (предприятиями), - с соответствующих основных (преобладающих, участвующих) обществ (предприятий), когда на их счета в банках поступает выручка за реализуемые товары (работы, услуги) зависимых (дочерних) обществ (предприятий);\n\nза организациями, являющимися в соответствии с гражданским законодательством Российской Федерации основными (преобладающими, участвующими) обществами (предприятиями), - с зависимых (дочерних) обществ (предприятий), когда на их счета в банках поступает выручка за реализуемые товары (работы, услуги) основных (преобладающих, участвующих) обществ (предприятий);\n\nза организациями, являющимися в соответствии с гражданским законодательством Российской Федерации зависимыми (дочерними) обществами (предприятиями), - с соответствующих основных (преобладающих, участвующих) обществ (предприятий), если с момента, когда организация, за которой числится задолженность, узнала или должна была узнать о назначении выездной налоговой проверки или о начале проведения камеральной налоговой проверки, произошла передача денежных средств, иного имущества основному (преобладающему, участвующему) обществу (предприятию) и если такая передача привела к невозможности взыскания указанной задолженности;\n\nза организациями, являющимися в соответствии с гражданским законодательством Российской Федерации основными (преобладающими, участвующими) обществами (предприятиями), - с зависимых (дочерних) обществ (предприятий), если с момента, когда организация, за которой числится задолженность, узнала или должна была узнать о назначении выездной налоговой проверки или о начале проведения камеральной налоговой проверки, произошла передача денежных средств, иного имущества зависимому (дочернему) обществу (предприятию) и если такая передача привела к невозможности взыскания указанной задолженности.\n\nЕсли налоговым органом в указанных случаях будет установлено, что выручка за реализуемые товары (работы, услуги) поступает на счета нескольких организаций, или если с момента, когда организация, за которой числится задолженность, узнала или должна была узнать о назначении выездной налоговой проверки или о начале проведения камеральной налоговой проверки, произошла передача денежных средств, иного имущества нескольким основным (преобладающим, участвующим) обществам (предприятиям), зависимым (дочерним) обществам (предприятиям), взыскание задолженности производится с соответствующих организаций пропорционально доле поступившей им выручки за реализуемые товары (работы, услуги), доле переданных денежных средств, стоимости иного имущества.\n\nПоложения настоящего подпункта также применяются, если налоговым органом в указанных случаях будет установлено, что перечисление выручки за реализуемые товары (работы, услуги), передача денежных средств, иного имущества основным (преобладающим, участвующим) обществам (предприятиям), зависимым (дочерним) обществам (предприятиям) были произведены через совокупность взаимосвязанных операций, в том числе в случае, если участники указанных операций не являются основными (преобладающими, участвующими) обществами (предприятиями), зависимыми (дочерними) обществами (предприятиями).\n\nПоложения настоящего подпункта также применяются, если налоговым органом в указанных случаях будет установлено, что перечисление выручки за реализуемые товары (работы, услуги), передача денежных средств, иного имущества производятся лицам, признанным судом иным образом зависимыми с налогоплательщиком, за которым числится задолженность.\n\nПри применении положений настоящего подпункта взыскание может производиться в пределах поступившей основным (преобладающим, участвующим) обществам (предприятиям), зависимым (дочерним) обществам (предприятиям), лицам, признанным судом иным образом зависимыми с налогоплательщиком, за которым числится задолженность, выручки за реализуемые товары (работы, услуги), переданных денежных средств, иного имущества.\n\nСтоимость имущества в указанных в настоящем подпункте случаях определяется как остаточная стоимость имущества, отраженная в бухгалтерском учете организации на момент, когда организация, за которой числится задолженность, узнала или должна была узнать о назначении выездной налоговой проверки или о начале проведения камеральной налоговой проверки;\n\n2) с организации или физического лица, в том числе являющегося индивидуальным предпринимателем, если их обязанность по уплате налога основана на изменении налоговым органом юридической квалификации сделки, совершенной таким налогоплательщиком, или статуса и характера деятельности этого налогоплательщика. (В редакции  Федерального закона от 31.07.2025 № 287-ФЗ)\n\nВ случае, указанном в абзаце первом настоящего подпункта, налоговый орган обращается в суд в течение шести месяцев со дня вступления в силу решений, указанных в подпункте 10 пункта 5 статьи 113 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n3) (Подпункт утратил силу - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n4. Взыскание задолженности, возникшей в связи с неуплатой или неполной уплатой налога декларантом, признаваемым таковым в соответствии с Федеральным законом от 8 июня 2015 года № 140-ФЗ \"О добровольном декларировании физическими лицами активов и счетов (вкладов) в банках и о внесении изменений в отдельные законодательные акты Российской Федерации\", и (или) иным лицом, информация о котором содержится в специальной декларации, представленной в соответствии с указанным Федеральным законом, не производится. Взыскание задолженности на основании настоящего пункта не производится при соблюдении одного из следующих условий:\n\n1) если обязанность по уплате такого налога возникла у декларанта и (или) иного лица в результате совершения до 1 января 2015 года операций, связанных с приобретением (формированием источников приобретения), использованием либо распоряжением имуществом (имущественными правами) и (или) контролируемыми иностранными компаниями, информация о которых содержится в специальной декларации, представленной в период с 1 июля 2015 года по 30 июня 2016 года, либо с открытием и (или) зачислением денежных средств на счета (вклады), информация о которых содержится в такой специальной декларации;\n\n2) если обязанность по уплате такого налога возникла у декларанта и (или) иного лица до 1 января 2018 года в результате совершения операций, связанных с приобретением (формированием источников приобретения), использованием либо распоряжением имуществом (имущественными правами) и (или) контролируемыми иностранными компаниями, информация о которых содержится в специальной декларации, представленной в период с 1 марта 2018 года по 28 февраля 2019 года, либо с открытием и (или) зачислением денежных средств на счета (вклады), информация о которых содержится в такой специальной декларации. При этом положения настоящего подпункта не распространяются на обязанность по уплате налогов, предусмотренных частью второй настоящего Кодекса, подлежащих уплате в отношении прибыли и (или) имущества контролируемых иностранных компаний;\n\n3) если обязанность по уплате такого налога возникла у декларанта и (или) иного лица до 1 января 2019 года в результате совершения операций, связанных с приобретением (формированием источников приобретения), использованием либо распоряжением имуществом (имущественными правами) и (или) контролируемыми иностранными компаниями, информация о которых содержится в специальной декларации, представленной в период с 1 июня 2019 года по 29 февраля 2020 года, либо с открытием и (или) зачислением денежных средств на счета (вклады), информация о которых содержится в такой специальной декларации. При этом положения настоящего подпункта не распространяются на обязанность по уплате налогов, предусмотренных частью второй настоящего Кодекса, подлежащих уплате в отношении прибыли и (или) имущества контролируемых иностранных компаний;\n\n4) если обязанность по уплате такого налога возникла у декларанта и (или) иного лица до 1 января 2022 года в результате совершения операций, связанных с приобретением (формированием источников приобретения), использованием либо распоряжением имуществом (имущественными правами) и (или) контролируемыми иностранными компаниями, информация о которых содержится в специальной декларации, представленной в ходе четвертого этапа декларирования в соответствии с Федеральным законом от 8 июня 2015 года № 140-ФЗ \"О добровольном декларировании физическими лицами активов и счетов (вкладов) в банках и о внесении изменений в отдельные законодательные акты Российской Федерации\", либо с открытием и (или) зачислением денежных средств на счета (вклады), информация о которых содержится в такой специальной декларации. При этом положения настоящего подпункта не распространяются на обязанность по уплате налогов, предусмотренных частью второй настоящего Кодекса, подлежащих уплате в отношении прибыли и (или) имущества контролируемых иностранных компаний.\n\n5. Сумма, подлежащая взысканию налоговыми органами на основании судебного акта, не может превышать размер отрицательного сальдо единого налогового счета налогоплательщика на дату исполнения такого судебного акта.\n\n6. Единый налоговый платеж учитывается на едином налоговом счете на основании информации, поступающей из Государственной информационной системы о государственных и муниципальных платежах, предусмотренной Федеральным законом от 27 июля 2010 года № 210-ФЗ \"Об организации предоставления государственных и муниципальных услуг\", со дня:\n\n1) предъявления в банк поручения на перечисление в бюджетную систему Российской Федерации на счет Федерального казначейства денежных средств со счета налогоплательщика (со счета иного лица в случае уплат\n\nы им налога за налогоплательщика) в банке при наличии на нем достаточного денежного остатка на день платежа;\n\n2) передачи физическим лицом в банк поручения на перечисление в бюджетную систему Российской Федерации на счет Федерального казначейства без открытия счета в банке денежных средств, предоставленных банку физическим лицом, при условии их достаточности для перечисления;\n\n3) отражения на лицевом счете организации, которой открыт лицевой счет, операции по перечислению соответствующих денежных средств в бюджетную систему Российской Федерации;\n\n4) внесения физическим лицом в банк, кассу местной администрации, организацию федеральной почтовой связи либо в многофункциональный центр предоставления государственных и муниципальных услуг наличных денежных средств для их перечисления в бюджетную систему Российской Федерации на счет Федерального казначейства;\n\n5) перечисления судебным приставом-исполнителем денежных средств в качестве единого налогового платежа, взысканных в рамках исполнительного производства в соответствии с Федеральным законом от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\". Денежные средства, перечисленные судебным приставом-исполнителем в качестве единого налогового платежа в рамках исполнительного производства в соответствии с Федеральным законом от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\", признаются уплаченными в счет исполнения требований по постановлению налогового органа о взыскании задолженности налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в бюджетную систему Российской Федерации за счет имущества либо судебного акта, содержащего требования о взыскании задолженности, вне зависимости от определения их принадлежности в соответствии с пунктом 8 настоящей статьи; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n6) предъявления в банк поручения на перечисление в бюджетную систему Российской Федерации на счет Федерального казначейства денежных средств со счета налогоплательщика или со счета иного лица в банке при наличии на нем достаточного денежного остатка на день платежа в счет возмещения ущерба, причиненного бюджетной системе Российской Федерации в результате преступлений, за совершение которых статьями 198 - 1992 Уголовного кодекса Российской Федерации предусмотрена уголовная ответственность. При этом зачет суммы указанных денежных средств в счет исполнения соответствующей обязанности по уплате налога производится в порядке, установленном федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n7. Обязанность по уплате налога считается исполненной (частично исполненной) налогоплательщиком, если иное не предусмотрено пунктом 13 настоящей статьи:\n\n1) со дня перечисления денежных средств в качестве единого налогового платежа в бюджетную систему Российской Федерации или со дня признания денежных средств в качестве единого налогового платежа при наличии на соответствующую дату учтенной на едином налоговом счете совокупной обязанности в части, в отношении которой может быть определена принадлежность таких сумм денежных средств в соответствии с пунктом 8 настоящей статьи;\n\n2) со дня, на который приходится срок уплаты налога, зачтенного в счет исполнения предстоящей обязанности по уплате такого налога; (В редакции  Федерального закона от 29.05.2023 № 196-ФЗ)\n\n3) со дня учета на едином налоговом счете совокупной обязанности в соответствии с пунктом 5 статьи 113 настоящего Кодекса при наличии на эту дату положительного сальдо единого налогового счета в части, в отношении которой может быть определена принадлежность сумм денежных средств, уплаченных (перечисленных) в качестве единого налогового платежа, в соответствии с пунктом 8 настоящей статьи;\n\n4) со дня зачета сумм денежных средств, формирующих положительное сальдо единого налогового счета, на основании заявления, представленного в соответствии с абзацем третьим пункта 4 статьи 78 настоящего Кодекса;\n\n5) со дня перечисления денежных средств не в качестве единого налогового платежа в счет исполнения обязанности по уплате государственной пошлины, в отношении уплаты которой арбитражным судом не выдан исполнительный документ, налога на профессиональный доход, сборов за пользование объектами животного мира и за пользование объектами водных биологических ресурсов, налога на сверхприбыль,  страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности. (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\nПеречни указанных в настоящем подпункте плательщиков страховых взносов устанавливаются в порядке, предусмотренном соответственно Федеральным законом от 27 ноября 2001 года № 155-ФЗ \"О дополнительном социальном обеспечении членов летных экипажей воздушных судов гражданской авиации\" и Федеральным законом от 10 мая 2010 года № 84-ФЗ \"О дополнительном социальном обеспечении отдельных категорий работников организаций угольной промышленности\";\n\n(Подпункт в редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n6) со дня удержания налоговым агентом сумм налога, если обязанность по исчислению и удержанию налога из денежных средств налогоплательщика возложена в соответствии с настоящим Кодексом на налогового агента.\n\n8. Принадлежность сумм денежных средств, перечисленных и (или) признаваемых в качестве единого налогового платежа, определяется налоговыми органами на основании учтенной на едином налоговом счете налогоплательщика суммы его совокупной обязанности с соблюдением следующей последовательности:\n\n1) недоимка по налогу на доходы физических лиц - начиная с наиболее раннего момента ее возникновения;\n\n2) налог на доходы физических лиц - с момента возникновения обязанности по его перечислению налоговым агентом;\n\n3) недоимка по иным налогам, сборам, страховым взносам - начиная с наиболее раннего момента ее возникновения;\n\n4) иные налоги, авансовые платежи, сборы, страховые взносы - с момента возникновения обязанности по их уплате (перечислению);\n\n6) проценты;\n\n7) штрафы.\n\n(Пункт в редакции  Федерального закона от 29.05.2023 № 196-ФЗ)\n\n1) отзыва лицом, предъявившим в банк поручение на перечисление в бюджетную систему Российской Федерации денежных средств в счет уплаты налога, или возврата банком такому лицу неисполненного поручения на перечисление соответствующих денежных средств в бюджетную систему Российской Федерации;\n\n2) отзыва организацией, которой открыт лицевой счет, или возврата органом Федерального казначейства (иным уполномоченным органом, осуществляющим открытие и ведение лицевых счетов) организации неисполненного поручения на перечисление соответствующих денежных средств в бюджетную систему Российской Федерации;\n\n3) возврата местной администрацией, организацией федеральной почтовой связи либо многофункциональным центром предоставления государственных и муниципальных услуг физическому лицу наличных денежных средств, принятых для их перечисления в бюджетную систему Российской Федерации;\n\n4) неправильного указания налогоплательщиком или иным лицом, предъявившим в банк поручение на перечисление в бюджетную систему Российской Федерации денежных средств в счет уплаты налога за налогоплательщика, в поручении на перечисление суммы налога номера счета Федерального казначейства и (или) наименования банка получателя, повлекшего неперечисление этой суммы в бюджетную систему Российской Федерации на счет Федерального казначейства;\n\n5) если на день предъявления налогоплательщиком (иным лицом, предъявившим в банк поручение на перечисление в бюджетную систему Российской Федерации денежных средств в счет уплаты налога за налогоплательщика) в банк (орган Федерального казначейства, иной уполномоченный орган, осуществляющий открытие и ведение лицевых счетов) поручения на перечисление денежных средств в счет уплаты налога этот налогоплательщик (иное лицо) имеет иные неисполненные требования, которые предъявлены к его счету (лицевому счету) и в соответствии с гражданским законодательством Российской Федерации исполняются в первоочередном порядке, и если на этом счете (лицевом счете) нет достаточного остатка для удовлетворения всех требований.\n\nПри перечислении суммы денежных средств в счет исполнения обязанности по уплате налогов иным лицом за налогоплательщика в платежном поручении указывается идентификационный номер налогоплательщика, за которого перечислены указанные денежные средства. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 45. Исполнение обязанности по уплате налога, сбора, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e59e603c9af1f39c3ddf5a40bd4bc78140cd99312a96b0ea0ba534cf3cb0db8a"},{"code_id":"NK_RF","article_number":"45.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 29.07.2018 № 232-ФЗ) (Утратила силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)","article_title":"Статья 45.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1022a236d92f41c6e0578965926fd08718eb674d63ddb5c22cff4b1bceb14c25"},{"code_id":"NK_RF","article_number":"45.2","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 29.11.2021 № 379-ФЗ) (Утратила силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)","article_title":"Статья 45.2. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a0b96b9523744d5a2467e68a849356aa5c24fe96b3df96e71eea480b8e7c36ff"}]$law7d0059$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
